{
  "name": "Infrastructure Domain Pattern",
  "description": "Protect an internal domain across text workflows.",
  "category": "infrastructure",
  "tags": [
    "ops",
    "safe-share"
  ],
  "is_active": true,
  "matcher": {
    "kind": "exact",
    "value": "internal.example.com",
    "case_sensitive": false,
    "applies_to": [
      "text",
      "structured_text"
    ]
  },
  "transformation": {
    "mode": "semantic",
    "semantic_label": "INTERNAL_DOMAIN"
  },
  "scope": {
    "workspace": "default"
  }
}

{
  "description": "Updated description for the saved pattern.",
  "tags": [
    "ops",
    "reviewed"
  ],
  "is_active": true
}

{
  "name": "Selected Internal Hostname",
  "selected_value": "vps-prod-01.internal",
  "description": "Created from a manual selection in a screenshot or pasted text.",
  "category": "hosts",
  "tags": [
    "selection",
    "ops"
  ],
  "transformation": {
    "mode": "semantic",
    "semantic_label": "PRIVATE_HOST"
  },
  "applies_to": [
    "text",
    "structured_text"
  ]
}

{
  "name": "Customer Names",
  "description": "Protect known customer names with a stable alias.",
  "category": "customers",
  "tags": [
    "crm"
  ],
  "is_active": true,
  "detection_definitions": [
    {
      "kind": "value_list",
      "values": [
        "Acme Corp",
        "Globex"
      ],
      "case_sensitive": false,
      "applies_to": [
        "text",
        "structured_text"
      ]
    }
  ],
  "transformation": {
    "mode": "stable_alias",
    "alias_prefix": "CUSTOMER"
  },
  "scope": {
    "workspace": "default"
  }
}

{
  "kind": "pack",
  "name": "Infrastructure Safe-Share Pack",
  "description": "Reusable pack for terminal text, logs, and VPS screenshots.",
  "category": "infrastructure",
  "tags": [
    "ops",
    "preset"
  ],
  "is_active": true,
  "pattern_ids": [
    "{{patternId}}"
  ],
  "custom_entity_ids": [
    "{{entityId}}"
  ],
  "default_text_transformation": {
    "mode": "semantic",
    "semantic_label": "SENSITIVE_VALUE"
  },
  "default_image_transformation": {
    "mode": "blur",
    "blur_radius": 10
  },
  "face_preferences": {
    "mode": "blur",
    "blur_radius": 12
  },
  "metadata": {
    "team": "platform"
  }
}

{
  "title": "Terminal safe-share review",
  "content": "Connect to https://internal.example.com from 10.0.0.1 as root",
  "content_type": "text",
  "apply_builtins": true,
  "pattern_ids": [
    "{{patternId}}"
  ],
  "custom_entity_ids": [
    "{{entityId}}"
  ],
  "configuration_ids": [
    "{{configurationId}}"
  ],
  "exact_values": [
    "root"
  ],
  "manual_spans": [],
  "default_transformation": {
    "mode": "semantic",
    "semantic_label": "SENSITIVE_VALUE"
  },
  "persist_job": true,
  "persist_source_content": true
}

{
  "title": "One-shot alias workflow",
  "content": "customer=acme customer=acme customer=globex",
  "content_type": "text",
  "apply_builtins": false,
  "exact_values": [
    "acme",
    "globex"
  ],
  "default_transformation": {
    "mode": "stable_alias",
    "alias_prefix": "CUSTOMER"
  },
  "persist_job": false
}

formdata.value:
{
  "title": "Screenshot safe-share export",
  "content_type": "screenshot",
  "configuration_ids": [
    "{{configurationId}}"
  ],
  "regions": [
    {
      "kind": "image_region",
      "source": "manual",
      "entity_type": "SECRET_REGION",
      "entity_name": "API key panel",
      "region": {
        "x": 48,
        "y": 24,
        "width": 240,
        "height": 96
      },
      "transformation": {
        "mode": "mask",
        "overlay_color": "#111111",
        "overlay_label": "REDACTED"
      }
    }
  ],
  "detect_faces": false,
  "persist_job": true
}
